static bool same_px(const char *what, const uint32_t *p, int w, int h, const std::vector<uint32_t> &want)
{
    s4_checks++;
    for (int i = 0; p && i < w * h; i++) if (p[i] != want[i]) { s4_failures++; fprintf(stderr, "  FAIL %s: pixel (%d,%d) = %08x, want %08x\n", what, i % w, i / w, p[i], want[i]); return false; }
    if (!p) { s4_failures++; fprintf(stderr, "  FAIL %s: no pixels\n", what); return false; }
    return true;
}
static void icon_check(const char *what, int id, int w, int h, const std::vector<uint32_t> &want)
{
    HICON ic = LoadIconA(MOD, MI(id));
    const uint32_t *px = NULL; int iw = 0, ih = 0, hx, hy;
    s4_checks++; if (!ic) { s4_failures++; fprintf(stderr, "  FAIL %s: LoadIconA failed (%lu)\n", what, (unsigned long)GetLastError()); return; }
    CHECK(fnvnx_icon_pixels(ic, &px, &iw, &ih, &hx, &hy)); CHECK_EQ(iw, w); CHECK_EQ(ih, h);
    if (iw == w && ih == h) same_px(what, px, w, h, want);
}

TEST(resource_png_icons)
{
    Node r; int n = 0;
    for (auto &c : PNGS) { add(r, K(3), K(500 + n), 0x409, c.png); add(r, K(14), K(500 + n), 0x409, grp(1, { { c.w, c.h, 32, (int)c.png.size(), 500 + n } })); n++; }
    int nb = 0;
    for (auto &c : PNGBAD) { add(r, K(3), K(600 + nb), 0x409, c.png); add(r, K(14), K(600 + nb), 0x409, grp(1, { { 5, 4, 32, (int)c.png.size(), 600 + nb } })); nb++; }
    add(r, K(3), K(700), 0x409, PNG_ANC); add(r, K(14), K(700), 0x409, grp(1, { { 5, 4, 32, (int)PNG_ANC.size(), 700 } }));
    bytes img = build_image(r);
    fnvnx_resource_set_image_for_test(MOD, img.data(), img.size());
    n = 0;
    for (auto &c : PNGS) { icon_check(c.n, 500 + n, c.w, c.h, c.px); n++; }
    CHECK(n >= 40);
    nb = 0;
    for (auto &c : PNGBAD) {
        HICON ic = LoadIconA(MOD, MI(600 + nb++));
        s4_checks++; if (ic) { s4_failures++; fprintf(stderr, "  FAIL png %s: loaded\n", c.n); }
        CHECK_EQ(GetLastError(), 13);
    }
    HICON a = LoadIconA(MOD, MI(700)); const uint32_t *px = NULL; int w, h, hx, hy;
    CHECK(a != NULL && fnvnx_icon_pixels(a, &px, &w, &h, &hx, &hy) && w == 5 && h == 4);
    if (a && w == 5 && h == 4) same_px("ancillary chunks", px, w, h, PNG_ANC_PX);   /* gAMA/sRGB/unknown ancillary chunks do not change the pixels */
    fnvnx_resource_set_image_for_test(MOD, NULL, 0);
}

TEST(resource_dib_encodings)
{
    Node r; int n = 0;
    for (auto &c : BMPS) add(r, K(2), K(800 + n++), 0x409, c.blob);
    n = 0; for (auto &c : BMPBAD) add(r, K(2), K(850 + n++), 0x409, c.blob);
    n = 0;
    for (auto &c : ICOS) { add(r, K(3), K(900 + n), 0x409, c.blob); add(r, K(14), K(900 + n), 0x409, grp(1, { { c.w, c.h, 32, (int)c.blob.size(), 900 + n } })); n++; }
    bytes img = build_image(r);
    fnvnx_resource_set_image_for_test(MOD, img.data(), img.size());
    n = 0;
    for (auto &c : BMPS) {
        void *l = ImageList_LoadImageA(MOD, MI(800 + n++), c.w, 1, 0xFFFFFFFFu, 0, 0);
        s4_checks++; if (!l) { s4_failures++; fprintf(stderr, "  FAIL dib %s: load failed (%lu)\n", c.n, (unsigned long)GetLastError()); continue; }
        int cx = 0, cy = 0; const uint32_t *p = NULL;
        CHECK_EQ(ImageList_GetImageCount(l), 1); ImageList_GetIconSize(l, &cx, &cy); CHECK_EQ(cx, c.w); CHECK_EQ(cy, c.h);
        CHECK(fnvnx_imagelist_pixels(l, 0, &p)); same_px(c.n, p, c.w, c.h, c.px);
        ImageList_Destroy(l);
    }
    n = 0;
    for (auto &c : BMPBAD) {
        void *l = ImageList_LoadImageA(MOD, MI(850 + n++), 2, 1, 0xFFFFFFFFu, 0, 0);
        s4_checks++; if (l) { s4_failures++; fprintf(stderr, "  FAIL dib %s: loaded\n", c.n); ImageList_Destroy(l); }
        CHECK_EQ(GetLastError(), 13);
    }
    n = 0;
    for (auto &c : ICOS) { icon_check(c.n, 900 + n, c.w, c.h, c.px); n++; }
    fnvnx_resource_set_image_for_test(MOD, NULL, 0);
}

static void put_file(const char *path, const bytes &b)
{
    HANDLE hf = CreateFileA(path, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
    DWORD put = 0; CHECK(hf != INVALID_HANDLE_VALUE && WriteFile(hf, b.data(), (DWORD)b.size(), &put, NULL)); CloseHandle(hf);
}
/* ICONDIR + entries: {w, h, bitcount-or-hotx, hoty, data} */
static bytes dirfile(int type, const std::vector<std::pair<std::vector<int>, bytes>> &e)
{
    bytes b; p16(b, 0); p16(b, type); p16(b, (unsigned)e.size());
    size_t off = 6 + 16 * e.size();
    for (auto &x : e) { b.push_back(x.first[0] & 255); b.push_back(x.first[1] & 255); b.push_back(0); b.push_back(0); p16(b, x.first[2]); p16(b, x.first[3]); p32(b, (uint32_t)x.second.size()); p32(b, (uint32_t)off); off += x.second.size(); }
    for (auto &x : e) b.insert(b.end(), x.second.begin(), x.second.end());
    return b;
}

TEST(resource_icon_files_and_invert)
{
    int cx, cy; const uint32_t *p = NULL;
    bytes i16 = icon_dib(16, 16, 4, true), i32 = icon_dib(32, 32, 8, true);
    put_file("C:\\FalloutNV\\a.ico", dirfile(1, { { { 16, 16, 4, 1 }, i16 }, { { 32, 32, 8, 1 }, i32 } }));
    void *il = ImageList_LoadImageA(NULL, "C:\\FalloutNV\\a.ico", 32, 1, 0xFFFFFFFFu, 1, 0x10);   /* IMAGE_ICON, LR_LOADFROMFILE: closest size */
    CHECK(il != NULL); CHECK_EQ(ImageList_GetImageCount(il), 1); ImageList_GetIconSize(il, &cx, &cy); CHECK_EQ(cx, 32); CHECK_EQ(cy, 32);
    CHECK(fnvnx_imagelist_pixels(il, 0, &p) && px_eq(p, 0, 0, 32, 0xFFFF0000u) && px_eq(p, 1, 0, 32, 0xFF00FF00u) && (p[16] >> 24) == 0);
    ImageList_Destroy(il);
    il = ImageList_LoadImageA(NULL, "C:\\FalloutNV\\a.ico", 16, 1, 0xFFFFFFFFu, 1, 0x10);
    CHECK(il != NULL); ImageList_GetIconSize(il, &cx, &cy); CHECK_EQ(cx, 16); CHECK_EQ(cy, 16);
    CHECK(fnvnx_imagelist_pixels(il, 0, &p) && px_eq(p, 2, 0, 16, 0xFF0000FFu) && (p[8] >> 24) == 0); ImageList_Destroy(il);
    /* a .ico holding a PNG image (the entry's bitcount 32) */
    put_file("C:\\FalloutNV\\p.ico", dirfile(1, { { { PNGS[0].w, PNGS[0].h, 32, 1 }, PNGS[0].png } }));
    il = ImageList_LoadImageA(NULL, "C:\\FalloutNV\\p.ico", PNGS[0].w, 1, 0xFFFFFFFFu, 1, 0x10);
    CHECK(il != NULL && fnvnx_imagelist_pixels(il, 0, &p)); if (il) same_px("ico png", p, PNGS[0].w, PNGS[0].h, PNGS[0].px); ImageList_Destroy(il);
    /* .cur: hotspot in the directory entry, DIB without the 4-byte hotspot prefix; XOR=1 AND=1 pixels are not drawn white */
    bytes cb = cursor_blob(); bytes cd(cb.begin() + 4, cb.end());
    put_file("C:\\FalloutNV\\c.cur", dirfile(2, { { { 32, 32, 5, 9 }, cd } }));
    il = ImageList_LoadImageA(NULL, "C:\\FalloutNV\\c.cur", 32, 1, 0xFFFFFFFFu, 2, 0x10);
    CHECK(il != NULL); CHECK(il && fnvnx_imagelist_pixels(il, 0, &p));
    if (il) { CHECK(px_eq(p, 1, 0, 32, 0xFFFFFFFFu)); CHECK(px_eq(p, 0, 0, 32, 0xFF000000u)); CHECK(px_eq(p, 21, 3, 32, 0)); CHECK(px_eq(p, 20, 3, 32, 0)); }
    ImageList_Destroy(il);
    CHECK(ImageList_LoadImageA(NULL, "C:\\FalloutNV\\c.cur", 32, 1, 0xFFFFFFFFu, 1, 0x10) == NULL); CHECK_EQ(GetLastError(), 13);   /* a cursor file is not an icon file */
    CHECK(ImageList_LoadImageA(NULL, "C:\\FalloutNV\\nofile.ico", 32, 1, 0xFFFFFFFFu, 1, 0x10) == NULL);
    { bytes f = dirfile(1, { { { 16, 16, 4, 1 }, i16 } }); f.resize(f.size() - 10); put_file("C:\\FalloutNV\\t.ico", f); }
    CHECK(ImageList_LoadImageA(NULL, "C:\\FalloutNV\\t.ico", 16, 1, 0xFFFFFFFFu, 1, 0x10) == NULL); CHECK_EQ(GetLastError(), 13);
    /* the invert mask of a resource cursor */
    bytes img = build_image(make_tree());
    fnvnx_resource_set_image_for_test(MOD, img.data(), img.size());
    HCURSOR cu = LoadCursorA(MOD, MI(7)); const uint8_t *m = NULL; const uint32_t *px = NULL; int w, h, hx, hy;
    CHECK(cu != NULL && fnvnx_icon_invert_mask(cu, &m) == 1 && m != NULL);
    CHECK(fnvnx_icon_pixels(cu, &px, &w, &h, &hx, &hy));
    if (m && px) {
        CHECK_EQ(m[3 * 32 + 21], 1); CHECK_EQ(px[3 * 32 + 21], 0u);     /* AND=1 XOR=1: invert the screen, not white */
        CHECK_EQ(m[3 * 32 + 20], 0);                                   /* AND=1 XOR=0: transparent */
        CHECK_EQ(m[1], 0); CHECK_EQ(m[0], 0);                          /* AND=0: drawn */
        int inv = 0; for (int i = 0; i < 32 * 32; i++) inv += m[i];
        CHECK_EQ(inv, 32 * 8 * 1);                                     /* x >= 16 and odd: 8 columns per row */
    }
    HICON ic = LoadIconA(MOD, "ONLY4"); m = (const uint8_t *)1;
    CHECK(ic && fnvnx_icon_invert_mask(ic, &m) == 1 && m == NULL);    /* an icon has no inverted pixel */
    CHECK_EQ(fnvnx_icon_invert_mask((HANDLE)(uintptr_t)8, &m), 0);
    /* production registration: the loader registers the image it mapped */
    const HMODULE M2 = (HMODULE)(uintptr_t)0x700000;
    fnvnx_resource_register_image(M2, img.data(), img.size());
    CHECK(FindResourceA(M2, "DATA", MI(10)) != NULL);
    fnvnx_resource_register_image(M2, NULL, 0);
    CHECK(FindResourceA(M2, "DATA", MI(10)) == NULL); CHECK_EQ(GetLastError(), 1812);
    fnvnx_resource_set_image_for_test(MOD, NULL, 0);
}

/* the rule "no platform lock is held across a call into the game" (tests/s4/test_nolock.cpp): the enumeration callback never returns */
static jmp_buf g_nlk_jb;
TEST(nlk_escape_resource_enumeration)
{
    bytes img = build_image(make_tree());
    fnvnx_resource_set_image_for_test(MOD, img.data(), img.size());
    struct E {
        static BOOL esc(HMODULE, LPCSTR, LPSTR, LONG_PTR) { longjmp(g_nlk_jb, 1); }
        static BOOL ok(HMODULE, LPCSTR, LPSTR, LONG_PTR l) { (*(int *)l)++; return TRUE; }
    };
    volatile bool escaped = false;
    if (setjmp(g_nlk_jb) == 0)
        EnumResourceNamesA(MOD, MI(10), E::esc, 0);
    else
        escaped = true;
    CHECK(escaped);
    CHECK_EQ(fnvnx_bnd_locks_held(), 0);
    static int n;
    n = 0;
    CHECK(EnumResourceNamesA(MOD, MI(10), E::ok, (LONG_PTR)&n));
    CHECK(n > 0);
    int n0 = n;
    test_thread([&] { n = 0; CHECK(EnumResourceNamesA(MOD, MI(10), E::ok, (LONG_PTR)&n)); CHECK_EQ(n, n0); }).join();
    CHECK(FindResourceA(MOD, MI(180), MI(2)) != NULL);
    fnvnx_resource_set_image_for_test(MOD, NULL, 0);
}
